{
  "rule": "Start at middle in a normal orientation: tilt left/right rolls the ball one slot in that named direction, saturating at edges; shake leaves the ball where it is but toggles to a reversed orientation, in which tilt left/right rolls the ball the opposite way.",
  "commitments": [
    {
      "events": ["tilt left", "shake", "tilt left", "tilt left"],
      "predict": "right",
      "why": "If this ended left or middle, the shake did not flip the direction of subsequent tilts as the rule requires."
    },
    {
      "events": ["tilt right", "shake", "tilt right", "tilt right"],
      "predict": "left",
      "why": "If this ended right or middle, the shake did not flip the direction of subsequent tilts as the rule requires."
    },
    {
      "events": ["shake", "tilt left", "tilt left"],
      "predict": "right",
      "why": "If this ended left or middle, shake does not invert tilt-left into a rightward roll."
    },
    {
      "events": ["shake", "tilt right", "tilt right"],
      "predict": "left",
      "why": "If this ended right or middle, shake does not invert tilt-right into a leftward roll."
    },
    {
      "events": ["tilt left", "shake", "tilt left"],
      "predict": "middle",
      "why": "If this ended left, the intervening shake did not flip the tilt direction; if right, the first tilt or edge saturation is wrong."
    }
  ]
}

{
  "rule": "The ball starts in the middle with a hidden mode that is normal. Shaking toggles the hidden mode without moving the ball; in normal mode tilt-left moves one slot left and tilt-right one slot right, while in reversed mode those directions are swapped, with the ball stopping at the ends.",
  "commitments": [
    {
      "events": ["shake", "tilt left", "tilt left", "tilt right"],
      "predict": "middle",
      "why": "An odd shake puts the hidden mode in reversed, so two left tilts push to the right edge and the right tilt brings it back to middle; another outcome would falsify the swap rule."
    },
    {
      "events": ["shake", "tilt left", "tilt right", "tilt left"],
      "predict": "right",
      "why": "Odd shake leaves reversed mode; left then right then left should push right, then back to middle, then right again, so any other result would doubt the reversed-direction rule."
    },
    {
      "events": ["tilt left", "shake", "tilt right", "tilt right"],
      "predict": "left",
      "why": "The shake flips to reversed mode at the left edge, where tilt-right should move or stay left, so a different result would cast doubt on the edge behavior in reversed mode."
    },
    {
      "events": ["tilt right", "shake", "tilt right", "tilt left"],
      "predict": "right",
      "why": "The shake flips to reversed mode at the right edge; tilt-right then tilt-left should return to right, so if it does not the reversal-at-edge rule is wrong."
    },
    {
      "events": ["shake", "tilt right", "tilt left", "tilt right"],
      "predict": "left",
      "why": "Odd shake means reversed mode; right moves left, left moves right, and right moves left again to end left, so a different result would falsify the toggle-and-reversal rule."
    }
  ]
}
